fig.suptitle('Marker data availability in the current 66-genome cohort',x=.05,y=.985,ha='left',fontsize=17,fontweight='bold')
fig.text(.05,.947,'BenA: 41/66  |  CaM: 43/66  |  RPB2: 66/66\n26 isolates have all three loci; 32 have two; 8 have RPB2 only.',fontsize=11)
fig.text(.05,.025,'Teal = at least one A/C/G/T base in the stored alignment; grey = no A/C/G/T.\nThis is availability, not validated locus completeness or evidence of gene deletion.\nRows follow the stored genome-tree tip order; topology is not drawn. Review: 10 November 2026.',fontsize=9,color='#48525d')
